import sys

def palindromepair(arr, N):
    def is_palindrome(s):
        return s == s[::-1]

    seen = set()
    for word in arr:
        seen.add(word)

    for word in arr:
        for i in range(len(word) + 1):
            left, right = word[:i], word[i:]
            if is_palindrome(left):
                rev_right = right[::-1]
                if rev_right in seen and rev_right != word:
                    return True
            if is_palindrome(right) and i != len(word):
                rev_left = left[::-1]
                if rev_left in seen and rev_left != word:
                    return True
    return False

input = sys.stdin.read().strip().split()
N = int(input[0])
arr = input[1:]
print(1 if palindromepair(arr, N) else 0)
